begin;
create table public.personal_lead_views(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(trim(name)) between 1 and 80),definition jsonb not null,revision integer not null default 1,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(organization_id,owner_id,name));
alter table public.personal_lead_views enable row level security;
revoke all on public.personal_lead_views from public,anon,authenticated;grant select on public.personal_lead_views to authenticated;
create policy own_lead_views on public.personal_lead_views for select to authenticated using(owner_id=auth.uid() and organization_id=(select public.lead_organization()));
create table public.lead_change_signals(organization_id uuid primary key references public.organizations(id) on delete cascade,revision uuid not null default gen_random_uuid());
alter table public.lead_change_signals enable row level security;revoke all on public.lead_change_signals from public,anon,authenticated;grant select on public.lead_change_signals to authenticated;
create policy own_lead_signals on public.lead_change_signals for select to authenticated using(organization_id=(select public.lead_organization()));
insert into public.lead_change_signals(organization_id)select id from public.organizations;
create function crm_private.signal_lead_change() returns trigger language plpgsql security definer set search_path='' as $$declare org uuid;begin
 if TG_OP='DELETE' then org=OLD.organization_id;else org=NEW.organization_id;end if;
 if exists(select 1 from public.organizations where id=org) then insert into public.lead_change_signals(organization_id)values(org)on conflict(organization_id)do update set revision=gen_random_uuid();end if;return null;
end$$;
revoke all on function crm_private.signal_lead_change() from public,anon,authenticated,service_role;
do $$declare tab text;begin foreach tab in array array['leads','lead_ingestion','call_attempts','confirmation_events','follow_ups','source_quiz_fields','lead_field_definitions','catalog_items','organization_memberships']loop execute format('create trigger lead_signal after insert or update or delete on public.%I for each row execute function crm_private.signal_lead_change()',tab);end loop;end$$;
do $$begin if exists(select 1 from pg_publication where pubname='supabase_realtime')and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='lead_change_signals')then execute 'alter publication supabase_realtime add table public.lead_change_signals';end if;end$$;
create index leads_org_updated on public.leads(organization_id,updated_at,id);
create index calls_filter_caller on public.call_attempts(organization_id,caller_id,lead_id);
create index confirmations_filter_caller on public.confirmation_events(organization_id,confirmed_by,lead_id);
create index ingestion_brand_snapshot on public.lead_ingestion(organization_id,(source_snapshot->'configured_attribution'->'brand'->>'id'));
create index ingestion_product_snapshot on public.lead_ingestion(organization_id,(source_snapshot->'configured_attribution'->'product'->>'id'));
create index ingestion_page_snapshot on public.lead_ingestion(organization_id,(source_snapshot->'configured_attribution'->'landing_page'->>'id'));
create function crm_private.validate_lead_view(d jsonb,org uuid) returns void language plpgsql set search_path='' as $$declare k text;v jsonb;txt text;cols text[];f record;begin
 if org is null then raise exception 'Operational staff required' using errcode='42501';end if;
 if jsonb_typeof(d) is distinct from 'object' or octet_length(d::text)>20000 or (select count(*) from jsonb_object_keys(d))<>20 or exists(select 1 from jsonb_object_keys(d)x where x not in('q','statuses','brands','products','landing_pages','sources','versions','callers','confirmers','created_from','created_to','updated_from','updated_to','callbacks','repeat','quiz','sort','direction','size','columns')) then raise exception 'Invalid view definition' using errcode='22023';end if;
 if jsonb_typeof(d->'size') is distinct from 'number' or jsonb_typeof(d->'q') is distinct from 'string' or length(d->>'q')>80 or coalesce(d->>'sort','') not in('created_at','updated_at','name') or coalesce(d->>'direction','') not in('asc','desc') or coalesce(d->>'size','') not in('5','10','20','50') or coalesce(d->>'callbacks','') not in('any','pending','overdue','none') or coalesce(d->>'repeat','') not in('any','repeat','first','unknown') then raise exception 'Invalid filter/sort settings' using errcode='22023';end if;
 foreach k in array array['statuses','brands','products','landing_pages','sources','versions','callers','confirmers']loop
 if jsonb_typeof(d->k) is distinct from 'array' or jsonb_array_length(d->k)>20 then raise exception 'Invalid filter group' using errcode='22023';end if;
 for v in select value from jsonb_array_elements(d->k)loop
 if jsonb_typeof(v)<>'string' then raise exception 'Invalid filter ID' using errcode='22023';end if;txt=v#>>'{}';
 if txt='unknown' and k in('brands','products','landing_pages','sources','versions')then continue;end if;
 if k='versions' then v=txt::jsonb;if jsonb_typeof(v)<>'array' or jsonb_array_length(v)<>2 or length(v->>1)>80 or not(exists(select 1 from public.source_form_versions where organization_id=org and source_id=(v->>0)::uuid and version_key=v->>1)or exists(select 1 from public.lead_ingestion where organization_id=org and source_id=(v->>0)::uuid and coalesce(source_snapshot->>'form_version','')=v->>1))then raise exception 'Unavailable source/version identity' using errcode='22023';end if;
 elsif k='statuses' then if not exists(select 1 from public.lead_statuses where organization_id=org and id=txt::uuid)then raise exception 'Unavailable status' using errcode='22023';end if;
 elsif k='sources' then if not exists(select 1 from public.ingestion_sources where organization_id=org and id=txt::uuid)then raise exception 'Unavailable source' using errcode='22023';end if;
 elsif k in('callers','confirmers')then if not exists(select 1 from public.organization_memberships where organization_id=org and user_id=txt::uuid)then raise exception 'Unavailable caller' using errcode='22023';end if;
 else if not exists(select 1 from public.catalog_items where organization_id=org and id=txt::uuid and kind=case k when 'brands' then 'brand' when 'products' then 'product' else 'landing_page' end)then raise exception 'Unavailable catalog reference' using errcode='22023';end if;end if;
 end loop;end loop;
 foreach k in array array['created_from','created_to','updated_from','updated_to']loop txt=d->>k;if txt is null or(txt<>'' and(txt!~'^\d{4}-\d{2}-\d{2}$' or txt<'1900-01-01' or txt>'2100-12-31' or to_char(txt::date,'YYYY-MM-DD')<>txt))then raise exception 'Invalid calendar date' using errcode='22023';end if;end loop;
 if d->>'created_from'<>'' and d->>'created_to'<>'' and d->>'created_from'>d->>'created_to' or d->>'updated_from'<>'' and d->>'updated_to'<>'' and d->>'updated_from'>d->>'updated_to' then raise exception 'Invalid date range' using errcode='22023';end if;
 select array_agg(id)into cols from public.quiz_columns();
 if jsonb_typeof(d->'columns') is distinct from 'array' or jsonb_array_length(d->'columns')>100 or exists(select 1 from jsonb_array_elements_text(d->'columns')x where not(x=any(coalesce(cols,'{}'))))then raise exception 'Selected quiz column unavailable; remove it explicitly' using errcode='22023';end if;
 if jsonb_typeof(d->'quiz') is distinct from 'array' or jsonb_array_length(d->'quiz')>5 then raise exception 'Invalid quiz predicates' using errcode='22023';end if;
 for v in select value from jsonb_array_elements(d->'quiz')loop if jsonb_typeof(v)<>'object' or(select count(*)from jsonb_object_keys(v))<>3 or exists(select 1 from jsonb_object_keys(v)x where x not in('field','operator','value')) or not(coalesce(v->>'field','')=any(coalesce(cols,'{}'))) or coalesce(v->>'operator','') not in('equals','not_equals','contains','missing','empty','present') or jsonb_typeof(v->'value') is distinct from 'string' or length(v->>'value')>1000 then raise exception 'Quiz field/operator unavailable; filters are never silently dropped' using errcode='22023';end if;end loop;
end$$;
create function crm_private.quiz_predicate(answers jsonb,source uuid,version_key text,pred jsonb,org uuid) returns boolean language plpgsql immutable set search_path='' as $$declare key text:=pred->>'key';scope uuid:=nullif(pred->>'source','')::uuid;present boolean;txt text;op text:=pred->>'operator';begin
 if scope is null and source is not null or scope is not null and(scope is distinct from source or pred->>'version' is distinct from version_key)then return false;end if;
 present=answers?key;txt=answers->>key;
 return case op when 'missing' then not present when 'empty' then present and txt='' when 'present' then present when 'equals' then present and txt=pred->>'value' when 'not_equals' then present and txt<>pred->>'value' when 'contains' then present and strpos(lower(txt),lower(pred->>'value'))>0 else false end;
end$$;
create function public.lead_filter_options() returns jsonb language plpgsql stable security definer set search_path='' as $$declare org uuid:=public.lead_organization();r jsonb:='{}';k text;catalog_kind text;begin
 if org is null then raise exception 'Operational staff required' using errcode='42501';end if;
 foreach k in array array['brands','products','landing_pages']loop catalog_kind=case k when 'brands' then 'brand' when 'products' then 'product' else 'landing_page' end;
 r=r||jsonb_build_object(k,coalesce((select jsonb_agg(x)from(select source_snapshot->'configured_attribution'->catalog_kind->>'id' value,string_agg(distinct source_snapshot->'configured_attribution'->kind->>'name',' / ')||case when bool_or(coalesce(c.archived,false))then ' (archived)' else '' end label from public.lead_ingestion i left join public.catalog_items c on c.organization_id=org and c.id::text=i.source_snapshot->'configured_attribution'->kind->>'id' where i.organization_id=org and i.source_snapshot->'configured_attribution'->kind->>'id' is not null group by 1 order by 2 limit 500)x),'[]'));
 end loop;
 return r||jsonb_build_object('sources',coalesce((select jsonb_agg(x)from(select distinct s.id::text value,s.name label from public.ingestion_sources s join public.lead_ingestion i on i.source_id=s.id where i.organization_id=org order by 2 limit 500)x),'[]'),'versions',coalesce((select jsonb_agg(x)from(select distinct jsonb_build_array(i.source_id::text,coalesce(i.source_snapshot->>'form_version',''))::text value,s.form_id||' / '||case when coalesce(i.source_snapshot->>'form_version','')='' then '(unversioned legacy)' else i.source_snapshot->>'form_version' end label from public.lead_ingestion i join public.ingestion_sources s on s.id=i.source_id where i.organization_id=org order by 2 limit 500)x),'[]'),'callers',coalesce((select jsonb_agg(x)from(select distinct a.caller_id::text value,p.full_name label from public.call_attempts a join public.staff_profiles p on p.id=a.caller_id where a.organization_id=org order by 2 limit 500)x),'[]'),'confirmers',coalesce((select jsonb_agg(x)from(select distinct e.confirmed_by::text value,p.full_name label from public.confirmation_events e join public.staff_profiles p on p.id=e.confirmed_by where e.organization_id=org order by 2 limit 500)x),'[]'),'fields',(select coalesce(jsonb_agg(to_jsonb(f)),'[]')from public.quiz_columns()f),'statuses',(select coalesce(jsonb_agg(to_jsonb(s)order by sort_order,label),'[]')from public.lead_statuses s where organization_id=org));
end$$;
create function public.advanced_lead_search(d jsonb,p_page integer default 1)returns jsonb language plpgsql stable security definer set search_path='' as $$declare org uuid:=public.lead_organization();result jsonb;sort text;dir text;sql text;predicates jsonb;begin
 perform crm_private.validate_lead_view(d,org);if p_page is null or p_page<1 or p_page>100000 then raise exception 'Invalid page' using errcode='22023';end if;
 select coalesce(jsonb_agg(p||jsonb_build_object('key',f.field_key,'source',f.source_id,'version',f.form_version)),'[]')into predicates from jsonb_array_elements(d->'quiz')p join public.quiz_columns()f on f.id=p->>'field';
 sort=case d->>'sort' when 'name' then 'lower(l.name)' when 'updated_at' then 'l.updated_at' else 'l.created_at' end;dir=case when d->>'direction'='asc' then 'asc' else 'desc' end;
 sql=$query$with filtered as materialized(select l.*,i.source_id,i.source_snapshot,i.is_repeat,i.lead_id is not null public_inquiry,p.historical_confirmed,p.source_at from public.leads l left join public.lead_ingestion i on i.lead_id=l.id left join public.lead_import_provenance p on p.lead_id=l.id where l.organization_id=$1
 and(($2->>'q')='' or strpos(lower(l.name),lower($2->>'q'))>0 or strpos(l.mobile_no,$2->>'q')>0)
 and(jsonb_array_length($2->'statuses')=0 or $2->'statuses'?l.status_id::text)
 and(($2->>'created_from')='' or l.created_at>=((nullif($2->>'created_from',''))::date::timestamp at time zone 'Asia/Kolkata'))
 and(($2->>'created_to')='' or l.created_at<(((nullif($2->>'created_to',''))::date+1)::timestamp at time zone 'Asia/Kolkata'))
 and(($2->>'updated_from')='' or l.updated_at>=((nullif($2->>'updated_from',''))::date::timestamp at time zone 'Asia/Kolkata'))
 and(($2->>'updated_to')='' or l.updated_at<(((nullif($2->>'updated_to',''))::date+1)::timestamp at time zone 'Asia/Kolkata'))
 and(jsonb_array_length($2->'brands')=0 or $2->'brands'?coalesce(i.source_snapshot->'configured_attribution'->'brand'->>'id','unknown'))
 and(jsonb_array_length($2->'products')=0 or $2->'products'?coalesce(i.source_snapshot->'configured_attribution'->'product'->>'id','unknown'))
 and(jsonb_array_length($2->'landing_pages')=0 or $2->'landing_pages'?coalesce(i.source_snapshot->'configured_attribution'->'landing_page'->>'id','unknown'))
 and(jsonb_array_length($2->'sources')=0 or $2->'sources'?coalesce(i.source_id::text,'unknown'))
 and(jsonb_array_length($2->'versions')=0 or i.source_id is null and $2->'versions'?'unknown' or exists(select 1 from jsonb_array_elements_text($2->'versions')v where v<>'unknown' and v::jsonb=jsonb_build_array(i.source_id::text,coalesce(i.source_snapshot->>'form_version',''))))
 and(jsonb_array_length($2->'callers')=0 or exists(select 1 from public.call_attempts a where a.lead_id=l.id and $2->'callers'?a.caller_id::text))
 and(jsonb_array_length($2->'confirmers')=0 or exists(select 1 from public.confirmation_events e where e.lead_id=l.id and $2->'confirmers'?e.confirmed_by::text))
 and(($2->>'callbacks')='any' or($2->>'callbacks')='none' and not exists(select 1 from public.follow_ups f where f.lead_id=l.id and f.state='pending')or($2->>'callbacks')in('pending','overdue')and exists(select 1 from public.follow_ups f where f.lead_id=l.id and f.state='pending' and(($2->>'callbacks')='pending' or f.due_at<now())))
 and(($2->>'repeat')='any' or($2->>'repeat')='unknown' and i.lead_id is null or($2->>'repeat')='repeat' and i.is_repeat or($2->>'repeat')='first' and not i.is_repeat)
 and not exists(select 1 from jsonb_array_elements($4)f where not crm_private.quiz_predicate(l.answers,i.source_id,coalesce(i.source_snapshot->>'form_version',''),f,$1)))
 select jsonb_build_object('total',(select count(*)from filtered),'leads',coalesce((select jsonb_agg(to_jsonb(page)order by SORT_EXPR DIR,id DIR)from(select filtered.*,source_snapshot->'configured_attribution' configured_attribution,case when source_id is null then null else jsonb_build_object('source_id',source_id,'form_version',coalesce(source_snapshot->>'form_version',''))end quiz_scope,case when historical_confirmed is null then null else jsonb_build_object('historical_confirmed',historical_confirmed,'source_at',source_at)end historical_import from filtered order by SORT_EXPR DIR,id DIR limit ($2->>'size')::integer offset ($3-1)*($2->>'size')::integer)page),'[]'))$query$;
 -- Only these hard-coded expressions enter SQL. All user values remain parameters.
 sql=replace(replace(sql,'SORT_EXPR',replace(sort,'l.','')),'DIR',dir);execute sql into result using org,d,p_page,predicates;
 return result||jsonb_build_object('fields',(select coalesce(jsonb_agg(to_jsonb(f)),'[]')from public.quiz_columns()f),'statuses',(select coalesce(jsonb_agg(to_jsonb(s)order by sort_order,label),'[]')from public.lead_statuses s where organization_id=org));
end$$;
create function public.save_personal_lead_view(p_id uuid,p_revision integer,p_name text,p_definition jsonb,p_delete boolean default false)returns uuid language plpgsql security definer set search_path='' as $$declare org uuid:=public.lead_organization();existing public.personal_lead_views;result uuid;begin
 if org is null then raise exception 'Operational staff required' using errcode='42501';end if;
 if p_revision is null or p_revision<0 or p_delete is null then raise exception 'Explicit revision/action required' using errcode='22023';end if;
 perform 1 from public.organization_memberships where user_id=auth.uid() and organization_id=org and active and role in('admin','manager','telecaller') for share;
 if not found then raise exception 'Active operational membership required' using errcode='42501';end if;
 if p_id is not null then select * into existing from public.personal_lead_views where id=p_id and organization_id=org and owner_id=auth.uid() for update;if not found then raise exception 'Personal view unavailable' using errcode='42501';end if;if existing.revision is distinct from p_revision then raise exception 'View changed; reload' using errcode='PT409';end if;if p_delete then delete from public.personal_lead_views where id=p_id;return p_id;end if;elsif p_revision<>0 or p_delete then raise exception 'Invalid create operation' using errcode='22023';end if;
 if p_name is null or length(trim(p_name))not between 1 and 80 then raise exception 'Name required' using errcode='22023';end if;perform crm_private.validate_lead_view(p_definition,org);
 if p_id is null then insert into public.personal_lead_views(organization_id,owner_id,name,definition)values(org,auth.uid(),trim(p_name),p_definition)returning id into result;else update public.personal_lead_views set name=trim(p_name),definition=p_definition,revision=revision+1,updated_at=clock_timestamp()where id=p_id returning id into result;end if;return result;
end$$;
revoke all on function crm_private.validate_lead_view(jsonb,uuid),crm_private.quiz_predicate(jsonb,uuid,text,jsonb,uuid) from public,anon,authenticated,service_role;
revoke all on function public.advanced_lead_search(jsonb,integer),public.lead_filter_options(),public.save_personal_lead_view(uuid,integer,text,jsonb,boolean) from public,anon;
grant execute on function public.advanced_lead_search(jsonb,integer),public.lead_filter_options(),public.save_personal_lead_view(uuid,integer,text,jsonb,boolean) to authenticated;
notify pgrst,'reload schema';commit;
